from pathlib import Path
import re
path = Path('source/fitz/load-bmp.c')
data = path.read_text(encoding='utf-8')

# Replace bmp_read_palette function body
pattern = re.compile(r"static const unsigned char \*\n\s*bmp_read_palette\(fz_context \*ctx, struct info \*info, const unsigned char \*begin, const unsigned char \*end, const unsigned char \*p\)\n\{.*?\n\}\n", re.S)

replacement = """static const unsigned char *
bmp_read_palette(fz_context *ctx, struct info *info, const unsigned char *begin, const unsigned char *end, const unsigned char *p)
{
\tint i, expected, present, entry_size;
\tconst unsigned char *bitmap;
\tsize_t avail, avail_to_end, avail_to_bitmap;
\tsize_t file_len, pal_off, bmp_off;

\tentry_size = palette_entry_size(info);
\tif (entry_size <= 0)
\t\tfz_throw(ctx, FZ_ERROR_GENERIC, "invalid palette entry size in bmp image");

\t/*
\t * Don\'t trust bitmapoffset when deciding how many palette entries are present.
\t * Crafted headers can set bitmapoffset past end-of-buffer (or before the
\t * palette start), leading to out-of-bounds reads.
\t */
\tfile_len = (size_t)(end - begin);
\tpal_off = (size_t)(p - begin);
\tbmp_off = (size_t)info->bitmapoffset;
\tif (bmp_off > file_len)
\t\tbmp_off = file_len;
\tif (bmp_off < pal_off)
\t\tbmp_off = pal_off;
\tbitmap = begin + bmp_off;

\texpected = fz_mini(info->colors, 1 << info->bitcount);
\tif (expected == 0)
\t\texpected = 1 << info->bitcount;

\t/* Clamp reads to both bitmapoffset and actual buffer end. */
\tavail_to_end = (size_t)(end - p);
\tavail_to_bitmap = (size_t)(bitmap - p);
\tavail = fz_mini(avail_to_end, avail_to_bitmap);
\tpresent = fz_mini(expected, (int)(avail / (size_t)entry_size));

\tfor (i = 0; i < present; i++)
\t{
\t\t/* ignore alpha channel even if present */
\t\tinfo->palette[3 * i + 0] = read8(p + i * entry_size + 2);
\t\tinfo->palette[3 * i + 1] = read8(p + i * entry_size + 1);
